import log = require( './index' );


// TESTS //

// The function returns a number...
{
	log( 1.0, 0.782 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	log( true, 0.782 ); // $ExpectError
	log( false, 0.782 ); // $ExpectError
	log( null, 0.782 ); // $ExpectError
	log( undefined, 0.782 ); // $ExpectError
	log( '5', 0.782 ); // $ExpectError
	log( [], 0.782 ); // $ExpectError
	log( {}, 0.782 ); // $ExpectError
	log( ( x: number ): number => x, 0.782 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	log( 1.0, true ); // $ExpectError
	log( 1.0, false ); // $ExpectError
	log( 1.0, null ); // $ExpectError
	log( 1.0, undefined ); // $ExpectError
	log( 1.0, '5' ); // $ExpectError
	log( 1.0, [] ); // $ExpectError
	log( 1.0, {} ); // $ExpectError
	log( 1.0, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	log(); // $ExpectError
	log( 1.0 ); // $ExpectError
	log( 1.0, 0.900, 3.4 ); // $ExpectError
}
